import{_ as r,a0 as p,w as l,s,ao as c,I as i,x as t,a1 as a,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"10 条真心有趣的 Linux 命令 | LCTT x X-CMD","titleTemplate":false,"description":"10 条真心有趣的 Linux 命令 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10 条真心有趣的 Linux 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10 条真心有趣的 Linux 命令 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150908 List Of 10 Funny Linux Commands","title":"10 条真心有趣的 Linux 命令","tag":"201509","desc":""},"relativePath":"201509/20150908 List Of 10 Funny Linux Commands.md","filePath":"[post].md"}'),d={name:"201509/20150908 List Of 10 Funny Linux Commands.md"};function m(u,e,w,g,h,f){const n=p("Link");return l(),s("div",null,[e[13]||(e[13]=c(`<h1 id="_10-条真心有趣的-linux-命令" tabindex="-1">10 条真心有趣的 Linux 命令 <a class="header-anchor" href="#_10-条真心有趣的-linux-命令" aria-label="Permalink to “10 条真心有趣的 Linux 命令”">​</a></h1><p><strong>在终端工作是一件很有趣的事情。今天，我们将会列举一些有趣得为你带来欢笑的Linux命令。</strong></p><h3 id="_1-rev" tabindex="-1">1. rev <a class="header-anchor" href="#_1-rev" aria-label="Permalink to “1. rev”">​</a></h3><p>创建一个文件，在文件里面输入几个单词，rev命令会将你写的东西反转输出到控制台。</p><pre><code># rev  &lt;file name&gt;
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0021.png" alt="Selection_002"></p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0011.png" alt="Selection_001"></p><h3 id="_2-fortune" tabindex="-1">2. fortune <a class="header-anchor" href="#_2-fortune" aria-label="Permalink to “2. fortune”">​</a></h3><p>这个命令没有被默认安装，用apt-get命令安装它，fortune命令会随机显示一些句子</p><pre><code>crank@crank-System:~$ sudo apt-get install fortune
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0031.png" alt="Selection_003"></p><p>利用fortune命令的<strong>_s</strong> 选项，他会限制一个句子的输出长度。</p><pre><code># fortune -s
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0042.png" alt="Selection_004"></p><h3 id="_3-yes" tabindex="-1">3. yes <a class="header-anchor" href="#_3-yes" aria-label="Permalink to “3. yes”">​</a></h3><pre><code># yes &lt;string&gt;
</code></pre><p>这个命令会不停打印字符串，直到用户把这进程给结束掉。</p><pre><code># yes unixmen
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0054.png" alt="Selection_005"></p><h3 id="_4-figlet" tabindex="-1">4. figlet <a class="header-anchor" href="#_4-figlet" aria-label="Permalink to “4. figlet”">​</a></h3><p>这个命令可以用apt-get安装，安装之后，在<strong>/usr/share/figlet</strong>可以看到一些ascii字体文件。</p><pre><code>cd /usr/share/figlet
</code></pre><hr><pre><code>#figlet -f &lt;font&gt;  &lt;string&gt;
#figlet -f big.flf unixmen
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0062.png" alt="Selection_006"></p><pre><code>#figlet -f block.flf  unixmen
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0072.png" alt="Selection_007"></p><p>当然，你也可以尝试使用其他的选项。</p><h3 id="_5-asciiquarium" tabindex="-1">5. asciiquarium <a class="header-anchor" href="#_5-asciiquarium" aria-label="Permalink to “5. asciiquarium”">​</a></h3><p>这个命令会将你的终端变成一个海洋馆。</p><p>下载term animator：</p><pre><code># wget http://search.cpan.org/CPAN/authors/id/K/KB/KBAUCOM/Term-Animation-2.4.tar.gz
</code></pre><p>安装并且配置这个包：</p><pre><code># tar -zxvf Term-Animation-2.4.tar.gz
# cd Term-Animation-2.4/
# perl Makefile.PL &amp;&amp; make &amp;&amp; make test
# sudo make install
</code></pre><p>接着安装下面这个包:</p><pre><code># apt-get install libcurses-perl
</code></pre><p>下载并且安装asciiquarium：</p><pre><code># wget http://www.robobunny.com/projects/asciiquarium/asciiquarium.tar.gz
# tar -zxvf asciiquarium.tar.gz 
# cd asciiquarium_1.0/
# cp asciiquarium /usr/local/bin/
</code></pre><p>执行如下命令：</p><pre><code># /usr/local/bin/asciiquarium
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/asciiquarium_1.1-perl_008.png" alt="asciiquarium_1.1 : perl_008"></p><h3 id="_6-bb" tabindex="-1">6. bb <a class="header-anchor" href="#_6-bb" aria-label="Permalink to “6. bb”">​</a></h3><pre><code># apt-get install bb
# bb
</code></pre><p>看看会输出什么？</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0092.png" alt="Selection_009"></p><h3 id="_7-sl" tabindex="-1">7. sl <a class="header-anchor" href="#_7-sl" aria-label="Permalink to “7. sl”">​</a></h3><p>有的时候你可能把 <strong>ls</strong> 误打成了 <strong>sl</strong>，其实 <strong>sl</strong> 也是一个命令，如果你打 sl的话，你会看到一个移动的火车头</p><pre><code># apt-get install sl
</code></pre><hr><pre><code># sl
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0122.png" alt="Selection_012"></p><h3 id="_8-cowsay" tabindex="-1">8. cowsay <a class="header-anchor" href="#_8-cowsay" aria-label="Permalink to “8. cowsay”">​</a></h3><p>一个很常见的命令，它会用ascii显示你想说的话。</p><pre><code>apt-get install cowsay
</code></pre><hr><pre><code># cowsay &lt;string&gt;
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0132.png" alt="Selection_013"></p><p>或者，你可以用其他的角色来取代默认角色来说这句话，这些角色都存储在<strong>/usr/share/cowsay/cows</strong>目录下</p><pre><code># cd /usr/share/cowsay/cows
</code></pre><hr><pre><code>cowsay -f ghostbusters.cow  unixmen
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0141.png" alt="Selection_014"></p><p>或者</p><pre><code># cowsay -f bud-frogs.cow Rajneesh
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0151.png" alt="Selection_015"></p><h3 id="_9-toilet" tabindex="-1">9. toilet <a class="header-anchor" href="#_9-toilet" aria-label="Permalink to “9. toilet”">​</a></h3><p>你没看错，这是个命令来的，他会将字符串以彩色的ascii字符串形式输出到终端</p><pre><code># apt-get install toilet
</code></pre><hr><pre><code># toilet --gay unixmen
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0161.png" alt="Selection_016"></p><pre><code>toilet -F border -F gay unixmen
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_020.png" alt="Selection_020"></p><pre><code>toilet  -f mono12 -F metal  unixmen
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0181.png" alt="Selection_018"></p><h3 id="_10-aafire" tabindex="-1">10. aafire <a class="header-anchor" href="#_10-aafire" aria-label="Permalink to “10. aafire”">​</a></h3><p>aafire能让你的终端燃起来。</p><pre><code># apt-get install libaa-bin
</code></pre><hr><pre><code># aafire
</code></pre><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0191.png" alt="Selection_019"></p><p>就这么多，祝你们在Linux终端玩得开心哈！！！</p><hr>`,83)),i("p",null,[e[1]||(e[1]=t("via: ",-1)),a(n,{href:"http://www.unixmen.com/list-10-funny-linux-commands/"},{default:o(()=>[...e[0]||(e[0]=[t("http://www.unixmen.com/list-10-funny-linux-commands/",-1)])]),_:1})]),i("p",null,[e[5]||(e[5]=t("作者：",-1)),a(n,{href:"http://www.unixmen.com/author/rajneesh/"},{default:o(()=>[...e[2]||(e[2]=[t("Rajneesh Upadhyay",-1)])]),_:1}),e[6]||(e[6]=t(" 译者：",-1)),a(n,{href:"https://github.com/tnuoccalanosrep"},{default:o(()=>[...e[3]||(e[3]=[t("tnuoccalanosrep",-1)])]),_:1}),e[7]||(e[7]=t(" 校对：",-1)),a(n,{href:"https://github.com/%E6%A0%A1%E5%AF%B9%E8%80%85ID"},{default:o(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=t("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:o(()=>[...e[9]||(e[9]=[t("Linux中国",-1)])]),_:1}),e[12]||(e[12]=t(" 荣誉推出",-1))])])}const S=r(d,[["render",m]]);export{b as __pageData,S as default};
